// 2) ชาติก่อนตามมาทวง
// ============================================================
function pastSave(){try{if(!S||S.fate&&S.fate._ps)return;const L=LS.get(PMK,[]);const kid=(S.children||[]).find(c=>c&&c.n);
 L.unshift({n:S.name,g:S.gender,w:WK(),a:S.age,c:String(S.cause||'').slice(0,60),sp:S.spouse||'',kid:kid?kid.n:'',nem:S.nem&&S.nem.n||'',nemA:S.nem&&S.nem.alive?1:0,k:+S.kills||0,ka:Math.round(+S.karma||0),t:Date.now()});
 LS.set(PMK,L.slice(0,12));F()._ps=1}catch(e){}}
function pastTry(){const f=F();if(f.pm||S.age<18||S.age>55||!P(.12))return false;const L=(LS.get(PMK,[])||[]).filter(x=>x&&x.n&&x.n!==S.name);if(!L.length)return false;
 const p=L[0],opts=[];if(p.kid)opts.push('kid');if(p.sp)opts.push('sp');if(p.nem&&p.nemA)opts.push('nem');if(!opts.length)opts.push('self');f.pm=1;const t=pick(opts);
 if(t==='kid')ask(`🕯️ ผู้อาวุโสที่ชื่อ${E(p.kid)}`,`ผู้อาวุโสคนหนึ่งชื่อ <b>${E(p.kid)}</b> ชื่อเดียวกับลูกของ <b>${E(p.n)}</b> ในชาติก่อนของคุณ วินาทีที่สบตา คุณจำแววตานั้นได้ ทั้งที่ไม่เคยเจอกันในชาตินี้<br><span class="tag2">ชาติก่อน: ${E(p.n)} · ${E(p.c)} อายุ ${p.a} ปี</span>`,[
  ['บอกความจริง','เขาจะเชื่อไหม',()=>{if(P(.5))eff({happy:15,int:5,deed:'past_kid'},`ชายชราน้ำตาไหล "พ่อ… ข้ารอมาทั้งชีวิต" เขาส่งตำราที่บรรพบุรุษสั่งให้เก็บไว้ "เผื่อพ่อกลับมา"`,'myth');else eff({happy:-5,fame:-5},'เขาคิดว่าคุณบ้า แล้วให้คนไล่ออกไป','bad')}],
  ['เก็บไว้ในใจ','',()=>{eff({happy:6,karma:2},`คุณแค่โค้งให้เขาแล้วเดินจากไป เขามองตามคุณจนลับตา`)}]]);
 else if(t==='sp')ask(`🌙 คนที่คุ้นเคยเกินไป`,`คุณเจอคนแปลกหน้าที่หัวเราะเหมือน <b>${E(p.sp)}</b> คู่ชีวิตของ${E(p.n)}ในชาติก่อนทุกอย่าง แม้แต่นิสัยเอียงคอเวลาฟัง`,[
  ['เข้าไปทัก','',()=>{if(P(.4))eff({happy:18,cha:5},'เขาหยุดชะงัก "แปลกจัง… ข้ารู้สึกเหมือนรอใครอยู่มานาน" ทั้งคู่คุยกันเหมือนไม่เคยห่างกัน','myth');else eff({happy:-4},'เขาเป็นแค่คนที่หน้าคล้าย ไม่จำอะไรได้เลย แต่ก็เป็นมิตรดี','')}],
  ['ปล่อยให้เป็นความทรงจำ','',()=>{eff({happy:4},'บางสิ่งควรจบในชาติของมัน')}]]);
 else if(t==='nem')ask(`👴 ศัตรูเก่าที่ยังไม่ตาย`,`<b>${E(p.nem)}</b> ศัตรูคู่แค้นของ${E(p.n)}ในชาติก่อน ยังมีชีวิตอยู่ ตอนนี้เป็นชายชราพิการนั่งขายชาอยู่ข้างทาง เขามองคุณแล้วมือที่ถือกาสั่น`,[
  ['ทวงแค้นชาติก่อน','',()=>{eff({karma:-8,happy:-6,side:-1},`${E(p.nem)}ไม่ขัดขืนเลย "ข้ารู้ว่าเจ้าจะกลับมา" ความแค้นข้ามชาติจบลง แต่ไม่รู้สึกดีอย่างที่คิด`,'bad')}],
  ['นั่งดื่มชากับเขา','',()=>{eff({karma:8,happy:12,int:4,deed:'past_tea'},`"ชาติก่อนเราฆ่ากันทำไมนะ" ${E(p.nem)}ถาม ทั้งคู่นึกไม่ออก แล้วหัวเราะจนไอ`)}]]);
 else ask(`🌀 ความฝันซ้ำๆ`,`คุณฝันซ้ำทุกคืนว่าเป็นคนชื่อ <b>${E(p.n)}</b> ที่${E(p.c)} ตอนอายุ ${p.a} ปี ในฝันมีที่ซ่อนของบางอย่างอยู่ใต้หินก้อนหนึ่ง`,[
  ['ออกตามหาหินก้อนนั้น','',()=>{if(P(.55))eff({money:rnd(400,1200),int:4},'หินก้อนนั้นมีอยู่จริง ใต้มันมีถุงเงินผุๆ ที่ตัวคุณในชาติก่อนซ่อนไว้','myth');else eff({happy:-3},'ตามหาทั้งปีแต่ไม่เจอ หรือมันแค่ความฝัน','')}],
  ['ไม่สนใจ','',()=>{eff({},'คุณเลิกฝันไปเอง แต่บางคืนยังสะดุ้งตื่น','')}]]);
 return true}

