rg:{w:['rg'],a:[25,60],steps:[
 (t)=>{t.nm=S.spouse||NM();return[`🫥 คนที่ลืมคุณ`,`เช้านี้ <b>${E(t.nm)}</b> มองหน้าคุณแล้วถามว่า "ท่านคือใคร" ทุกคนจำเขาได้ แต่เขาจำคุณไม่ได้คนเดียว<br>เสียงในหัว: "การย้อนกาลไม่เคยฟรี ทุกรอบต้องจ่ายด้วยความทรงจำของใครสักคน"`,[
  ['เริ่มทำความรู้จักใหม่ตั้งแต่ต้น','',()=>{if(P(.6))eff({happy:10,cha:4},`${E(t.nm)}หลงรักคุณอีกครั้ง ครั้งนี้เร็วกว่าเดิมด้วย`);else eff({happy:-10},`${E(t.nm)}เลือกเดินจากไป ในโลกที่ไม่เคยมีคุณ เขามีความสุขดี`,'bad')}],
  ['สาบานว่าจะไม่ย้อนกาลอีก','',()=>eff({karma:5,happy:-4,deed:'rg_cost'},'คุณเก็บพลังย้อนกาลไว้ ยอมให้ความผิดพลาดที่เหลือเป็นของจริง')]]]}]},
