sky:{w:['sky'],a:[18,60],steps:[
 (t)=>[`🗳️ ประชามตินครกำแพง`,`คลื่นผู้อพยพหมื่นคนมาถึงหน้ากำแพง เสบียงในนครพอเลี้ยงคนเดิมได้แค่สามปี สภานครให้ประชาชนทุกคนโหวต<br><span class="tag2">โหวตนี้นับรวมกับผู้เล่นจริงทั้งเว็บ ผลรวมดูได้ที่ 📜 พงศาวดาร</span>`,[
  ['🚪 เปิดประตู','',()=>{F().kv='a';t.k='a';eff({karma:5,side:1,deed:'sky_open'},'คุณโหวตเปิดประตู')}],
  ['🧱 ปิดตาย','',()=>{F().kv='b';t.k='b';eff({karma:-2},'คุณโหวตปิดประตู','')}],
  ['ออกไปอยู่กับผู้อพยพนอกกำแพง','ถูกถอดสัญชาตินคร',()=>{F().kv='a';t.k='out';eff({fame:-20,happy:6,karma:8,deed:'sky_exile'},'คุณเดินออกประตูไปพร้อมกระเป๋าใบเดียว ข้างนอกกว้างกว่าที่คิด','epic')}]]],
 (t)=>{const j=ERA_NOW,a=+(j&&j.prev&&j.prev.ka)||0,b=+(j&&j.prev&&j.prev.kb)||0,open=a>=b;return[`🗳️ ผลประชามติ`,`ผลประชามติจากคนทั้งนคร (ผู้เล่นทั้งเว็บสัปดาห์ที่แล้ว: เปิด ${a} · ปิด ${b}) ประตูนคร<b>${open?'เปิด':'ปิดตาย'}</b>`,[
  ['ยอมรับผล','',()=>eff(open?(t.k==='b'?{happy:-4,money:-100}:{happy:8,fame:10}):(t.k==='a'?{happy:-8,karma:2}:{money:300,happy:-2}),open?'นครแออัดขึ้น ข้าวแพงขึ้น แต่เด็กอพยพหัวเราะเต็มลานกว้าง':'นครปลอดภัย เสบียงพอ แต่คืนนั้นได้ยินเสียงคนเคาะกำแพงไม่หยุด',open?'epic':'')]]]}]},
