function twTry(){const f=F(),w=WK();for(const id in TW){const T=TW[id];if(!T.w.includes(w))continue;let t=f.tw[id];
  if(!t){if(S.age<T.a[0]||S.age>T.a[1])continue;if(T.need&&!T.need())continue;if(!P(id==='scar'?.15:id==='short'||id==='junk'?.6:.2))continue;t=f.tw[id]={st:0,nx:S.age}}
  if(t.fin||S.age<t.nx)continue;const step=T.steps[t.st];if(!step){t.fin=1;continue}
  const r=step(t);t.st++;t.nx=S.age+(id==='short'?16:rnd(3,8));if(t.st>=T.steps.length)t.fin=1;
  if(r==='__wait'){t.st--;t.fin=0;t.nx=S.age+1;continue}if(r==='__')return true;if(!r)continue;ask(r[0],r[1],r[2]);return true}
 return false}

